const payload = $input.first()?.json;
const execution = payload && typeof payload === 'object' && !Array.isArray(payload) && payload.execution && typeof payload.execution === 'object' && !Array.isArray(payload.execution) ? payload.execution : {};
const workflow = payload && typeof payload === 'object' && !Array.isArray(payload) && payload.workflow && typeof payload.workflow === 'object' && !Array.isArray(payload.workflow) ? payload.workflow : {};
const rawId = typeof execution.id === 'string' ? execution.id.trim() : '';
const validId = rawId.length > 0 && rawId.length <= 4096;
const workflowName = typeof workflow.name === 'string' ? workflow.name.trim() : '';
let sourceKind = workflowName === 'TENDER — Агентский анализ — Запуск' ? 'dispatch' : workflowName === 'TENDER — Агентский анализ — Монитор' ? 'monitor' : 'unsupported_workflow';
if (!validId) sourceKind = 'invalid_identity';
const error = execution.error && typeof execution.error === 'object' && !Array.isArray(execution.error) ? execution.error : {};
const candidate = [error.message, error.description].find((value) => typeof value === 'string' && value.trim()) || '';
const unsafe = /https?:\/\/|(?:authorization|cookie|password|secret|api[\s_-]*key|access[_-]?token|bearer|token)(?:\s*(?::|=|\bis\b)|\s+)/iu.test(candidate);
const cleaned = candidate.replace(/[\u0000-\u001F\u007F]/gu, ' ').replace(/\s+/gu, ' ').trim();
const fallback = sourceKind === 'monitor' ? 'Agentic monitor workflow failed' : sourceKind === 'dispatch' ? 'Agentic dispatch workflow failed' : 'Agentic workflow error was not attributable';
const errorMessage = unsafe || !cleaned ? fallback : cleaned.slice(0, 500);
const errorCode = sourceKind === 'dispatch' ? 'DISPATCH_WORKFLOW_FAILED' : sourceKind === 'monitor' ? 'MONITOR_WORKFLOW_FAILED' : sourceKind === 'invalid_identity' ? 'AGENTIC_ERROR_IDENTITY_INVALID' : 'AGENTIC_ERROR_WORKFLOW_UNSUPPORTED';
return [{ json: { source_kind: sourceKind, execution_id: validId ? rawId : null, error_code: errorCode, error_message: errorMessage } }];
